/* Types */
export type Album = {
	id: number,
	title: string,
	artist: string | null,
	artistId: number | null,
	year: number | null,
	trackCount: number,
	durationMs: number,
	/**  Cover hash for the `sonder-art` scheme. */
	art: string | null,
	/**  The cover's dominant vivid colours (`#rrggbb`), most dominant first; may be empty. */
	artColors: string[],
};

export type AlbumInfo = {
	album: Album,
	tracks: TrackItem[],
};

export type AlbumPage = {
	/**  Albums in the whole library, for sizing the grid before every page is loaded. */
	total: number,
	offset: number,
	albums: Album[],
};

/**  Error returned by every command: a message the UI can show. */
export type AppError = string;

export type Artist = {
	id: number,
	name: string,
	albumCount: number,
	trackCount: number,
	/**  A cover to show for the artist (their newest album's), if any. */
	art: string | null,
};

export type ArtistInfo = {
	artist: Artist,
	albums: Album[],
	appearsOn: Album[],
};

/**  One AutoEQ result: a headphone as one source measured it. */
export type AutoEqResult = {
	name: string,
	/**  Who measured it (oratory1990, crinacle, Rtings…). */
	source: string,
	/**  The measurement rig, when the source used several. */
	rig: string | null,
	/**  Folder of the result in the AutoEQ repository; passed back to `autoeq_import`. */
	path: string,
};

/**  The RBJ filter shapes the EQ offers. */
export type BiquadKindSetting = "peak" | "lowShelf" | "highShelf" | "lowPass" | "highPass" | "bandPass" | "notch";

/**  Convolution with an impulse response file. */
export type ConvolutionSetting = {
	enabled?: boolean,
	/**  WAV file holding the response. */
	path?: string | null,
};

/**  A change to the cover embedded in a file. */
export type CoverChange = { kind: "keep" } | 
/**  Removes every embedded picture. */
{ kind: "remove" } | 
/**  Makes this JPEG or PNG (base64) the front cover. */
{ kind: "set"; data: string };

/**  An image for the UI to show: a JPEG or PNG, base64-encoded. */
export type CoverImage = {
	mime: string,
	data: string,
};

/**  How Now Playing shows the cover. */
export type CoverStyle = 
/**  The cover as the label of a spinning record, under a tonearm. */
"vinyl" | 
/**  The flat square cover. */
"square" | 
/**  Stage lyrics visualizer with Flow motion. */
"stage";

/**  Equal-power crossfade between queue entries. */
export type CrossfadeSetting = {
	enabled?: boolean,
	/**  Fade length in seconds, within the engine's 1–10 s range. */
	seconds?: number | null,
};

/**  Headphone crossfeed presets (libbs2b's). */
export type CrossfeedPresetSetting = 
/**  700 Hz, 4.5 dB. */
"default" | 
/**  700 Hz, 6.0 dB. */
"chuMoy" | 
/**  650 Hz, 9.5 dB. */
"janMeier";

/**  Headphone crossfeed. */
export type CrossfeedSetting = {
	enabled?: boolean,
	preset?: CrossfeedPresetSetting,
};

export type Device = {
	id: string,
	name: string,
	isDefault: boolean,
	selected: boolean,
	/**
	 *  Stereo formats the device accepts in exclusive mode (empty when it could not be
	 *  probed, for example while another app holds it).
	 */
	formats: OutputInfo[],
};

export type DevicesChangedEvent = Device[];

/**  How DSD files reach an output device. */
export type DsdMode = 
/**  DSD over PCM, bit-perfect; converted to PCM when the device does not take DoP. */
"dop" | 
/**  Native DSD where the driver exposes it (ALSA), else DoP, else PCM. */
"native" | 
/**  Always converted to PCM. */
"pcm";

/**  Output rate of DSD→PCM conversion. */
export type DsdPcmRate = "hz176400" | "hz352800";

/**  The set of favorited tracks changed. */
export type FavoritesChangedEvent = null;

/**  Filter phase choice for Sonder-designed tables. */
export type FilterPhaseSetting = "linear" | "minimum";

/**  Which tables serve a rate conversion. */
export type FilterSourceSetting = 
/**  Sonder designs its own filters at runtime (shipped). */
"sonder" | 
/**  Roon's tables from a folder the user owns. */
"roon";

/**  Filter sharpness choice for Sonder-designed tables. */
export type FilterVariantSetting = "precise" | "smooth";

/**  Lyrics found online for the editor, as the text Save would store in the file. */
export type FoundLyrics = {
	/**  The service's name. */
	source: string,
	/**  The text is LRC, with a time on every line. */
	synced: boolean,
	/**  The service says the track has no vocals; the text is empty. */
	instrumental: boolean,
	text: string,
};

export type GdriveCacheStats = {
	totalBytes: number,
	maxBytes: number,
	chunkCount: number,
	fileCount: number,
};

export type GdriveFolderItem = {
	id: string,
	name: string,
};

export type GdriveStatus = {
	configured: boolean,
	clientId: string,
	hasClientSecret: boolean,
	envOverride: boolean,
	hasApiKey: boolean,
	envApiKey: boolean,
	authenticated: boolean,
	accountEmail: string | null,
	syncing: boolean,
};

export type GdriveSyncFinishedEvent = {
	added: number,
	updated: number,
	removed: number,
	unchanged: number,
	failureCount: number,
	error: string | null,
};

export type GdriveSyncPhase = "listing" | "reading" | "writing";

export type GdriveSyncProgressEvent = {
	phase: GdriveSyncPhase,
	folderName: string,
	done: number,
	total: number,
};

export type GdriveSyncedFolder = {
	id: number,
	folderId: string,
	name: string,
	authMode: string,
	remoteKind: string,
	trackCount: number,
	addedAt: number,
};

/**
 *  How much frosted glass the UI draws. Blur is the costliest effect in the UI; `Off` keeps the
 *  same layout with opaque surfaces.
 */
